329	/// Collect triggered abilities from events and add them to the stack
330	/// in APNAP order (active player first on bottom, non-active player on top).
331	///
332	/// Does NOT resolve them — the game loop resolves them one at a time,
333	/// giving players priority between each.
334	pub fn collect_triggers(state: &mut GameState, registry: &CardRegistry) {
335	    let events = state.events.clone();
336	    let start = state.trigger_event_index;
337	    let active_player = state.active_player;
338	
339	    let mut ap_triggers: Vec<PendingTrigger> = Vec::new();
340	    let mut nap_triggers: Vec<PendingTrigger> = Vec::new();
341	
342	    for (i, event) in events.iter().enumerate().skip(start) {
343	        match event {
344	            GameEvent::EnteredBattlefield { object, .. } => {
345	                let (card_id, controller) = match state.get_object(*object) {
346	                    Some(o) if o.zone == Zone::Battlefield => (o.card_id, o.controller),
347	                    _ => continue,
348	                };
349	                // Only collect if the card has an on_enter_battlefield handler.
350	                // Self ETB trigger.
351	                if registry.get(card_id).is_some() {
352	                    let desc = trigger_description(registry, card_id, &crate::cards::TriggerKind::EntersBattlefield, false);
353	                    let trigger = PendingTrigger::EnteredBattlefield {
354	                        object_id: *object,
355	                        card_id,
356	                        controller,
357	                        description: desc,
358	                    };
359	                    if controller == active_player {
360	                        ap_triggers.push(trigger);
361	                    } else {
362	                        nap_triggers.push(trigger);
363	                    }
364	                }
365	
366	                // ETB-watch: notify other permanents that a creature entered.
367	                if state.get_object(*object).map(|o| o.power.is_some()).unwrap_or(false) {
368	                    let watchers: Vec<(ObjectId, CardId, PlayerId)> = state.objects.values()
369	                        .filter(|o| o.zone == Zone::Battlefield && o.id != *object)
370	                        .map(|o| (o.id, o.card_id, o.controller))
371	                        .collect();
372	                    for (watcher_id, watcher_card_id, watcher_controller) in watchers {
373	                        if registry.get(watcher_card_id).is_some() {
374	                            let desc = trigger_description(registry, watcher_card_id, &crate::cards::TriggerKind::AnyCreatureEnters, false);
375	                            if !desc.is_empty() {
376	                                let trigger = PendingTrigger::EnterWatch {
377	                                    watcher_id,
378	                                    watcher_card_id,
379	                                    controller: watcher_controller,
380	                                    entered_id: *object,
381	                                    entered_controller: controller,
382	                                    description: desc,
383	                                };
384	                                if watcher_controller == active_player {
385	                                    ap_triggers.push(trigger);
386	                                } else {
387	                                    nap_triggers.push(trigger);
388	                                }
389	                            }
390	                        }
391	                    }
392	                }
393	            }
394	            GameEvent::CreatureDied { object, card_id, controller, damaged_by, last_known_toughness } => {
395	                let dead_id = *object;
396	                let dead_card_id = *card_id;
397	                let dead_controller = *controller;
398	                let dead_damaged_by = damaged_by.clone();
399	                let dead_toughness = *last_known_toughness;
400	
401	                // 1. Self-dies trigger.
402	                if registry.get(dead_card_id).is_some() {
403	                    let desc = trigger_description(registry, dead_card_id, &crate::cards::TriggerKind::SelfDies, false);
404	                    let trigger = PendingTrigger::SelfDies {
405	                        dead_id,
406	                        dead_card_id,
407	                        controller: dead_controller,
408	                        description: desc,
409	                    };
410	                    if dead_controller == active_player {
411	                        ap_triggers.push(trigger);
412	                    } else {
413	                        nap_triggers.push(trigger);
414	                    }
415	                }
416	
417	                // 2. Death-watch: collect triggers from all permanents on battlefield.
418	                let watchers: Vec<(ObjectId, CardId, PlayerId)> = state.objects.values()
419	                    .filter(|o| o.zone == Zone::Battlefield && o.id != dead_id)
420	                    .map(|o| (o.id, o.card_id, o.controller))
421	                    .collect();
422	                for (watcher_id, watcher_card_id, watcher_controller) in watchers {
423	                    if registry.get(watcher_card_id).is_some() {
424	                        let desc = trigger_description(registry, watcher_card_id, &crate::cards::TriggerKind::AnyCreatureDies, false);
425	                        let trigger = PendingTrigger::DeathWatch {
426	                            watcher_id,
427	                            watcher_card_id,
428	                            controller: watcher_controller,
429	                            dead_id,
430	                            dead_controller,
431	                            dead_damaged_by: dead_damaged_by.clone(),
432	                            dead_toughness,
433	                            description: desc,
434	                        };
435	                        if watcher_controller == active_player {
436	                            ap_triggers.push(trigger);
437	                        } else {
438	                            nap_triggers.push(trigger);
439	                        }
440	                    }
441	                }
442	            }
443	            GameEvent::LeftBattlefield { object, .. } => {
444	                let (card_id,) = match state.get_object(*object) {
445	                    Some(o) => (o.card_id,),
446	                    None => continue,
447	                };
448	                if registry.get(card_id).is_some() {
449	                    let desc = trigger_description(registry, card_id, &crate::cards::TriggerKind::LeavesBattlefield, false);
450	                    let trigger = PendingTrigger::LeftBattlefield {
451	                        object_id: *object,
452	                        card_id,
453	                        description: desc,
454	                    };
455	                    // LTB triggers go on AP side (they're usually self-referential).
456	                    ap_triggers.push(trigger);
457	                }
458	            }
459	            GameEvent::CombatDamageDealt { source, target, amount } => {
460	                // Creature-to-creature combat damage triggers.
461	                if let crate::events::DamageTarget::Object(damaged_id) = target {
462	                    let source_id = *source;
463	                    if let Some(obj) = state.get_object(source_id) {
464	                        if obj.zone == Zone::Battlefield && obj.power.is_some() {
465	                            let card_id = obj.card_id;
466	                            let controller = obj.controller;
467	                            if registry.get(card_id).is_some() {
468	                                let desc = trigger_description(registry, card_id, &crate::cards::TriggerKind::DealsCombatDamageToCreature, false);
469	                                if !desc.is_empty() {
470	                                    let trigger = PendingTrigger::CombatDamageToCreature {
471	                                        creature_id: source_id,
472	                                        creature_card_id: card_id,
473	                                        controller,
474	                                        damaged_creature: *damaged_id,
475	                                        amount: *amount,
476	                                        description: desc,
477	                                    };
478	                                    if controller == active_player {
479	                                        ap_triggers.push(trigger);
480	                                    } else {
481	                                        nap_triggers.push(trigger);
482	                                    }
483	                                }
484	                            }
485	                        }
486	                    }
487	                }
488	                // Creature-to-player combat damage triggers.
489	                if let crate::events::DamageTarget::Player(damaged_player) = target {
490	                    let source_id = *source;
491	                    if let Some(obj) = state.get_object(source_id) {
492	                        if obj.zone == Zone::Battlefield && obj.power.is_some() {
493	                            let card_id = obj.card_id;
494	                            let controller = obj.controller;
495	
496	                            // Source's own combat damage trigger (requires registered card).
497	                            if registry.get(card_id).is_some() {
498	                                let desc = trigger_description(registry, card_id, &crate::cards::TriggerKind::CombatDamageToPlayer, false);
499	                                if !desc.is_empty() {
500	                                    let trigger = PendingTrigger::CombatDamageToPlayer {
501	                                        creature_id: source_id,
502	                                        creature_card_id: card_id,
503	                                        controller,
504	                                        damaged_player: *damaged_player,
505	                                        amount: *amount,
506	                                        description: desc,
507	                                    };
508	                                    if controller == active_player {
509	                                        ap_triggers.push(trigger);
510	                                    } else {
511	                                        nap_triggers.push(trigger);
512	                                    }
513	                                }
514	                            }
515	
516	                            // Combat damage watchers and any-damage watchers.
517	                            // Includes self — cards like Rakish Heir watch their own damage.
518	                            let watchers: Vec<(ObjectId, CardId, PlayerId)> = state.objects.values()
519	                                .filter(|o| o.zone == Zone::Battlefield)
520	                                .map(|o| (o.id, o.card_id, o.controller))
521	                                .collect();
522	                            for (watcher_id, watcher_card_id, watcher_controller) in watchers {
523	                                if registry.get(watcher_card_id).is_some() {
524	                                    // AnyCombatDamageToPlayer watchers.
525	                                    let desc = trigger_description(registry, watcher_card_id, &crate::cards::TriggerKind::AnyCombatDamageToPlayer, false);
526	                                    if !desc.is_empty() {
527	                                        let trigger = PendingTrigger::CombatDamageWatch {
528	                                            watcher_id,
529	                                            watcher_card_id,
530	                                            controller: watcher_controller,
531	                                            source_id,
532	                                            damaged_player: *damaged_player,
533	                                            amount: *amount,
534	                                            description: desc,
535	                                        };
536	                                        if watcher_controller == active_player {
537	                                            ap_triggers.push(trigger);
538	                                        } else {
539	                                            nap_triggers.push(trigger);
540	                                        }
541	                                    }
542	                                    // AnyDamageToPlayer watchers (combat damage is also damage).
543	                                    let desc2 = trigger_description(registry, watcher_card_id, &crate::cards::TriggerKind::AnyDamageToPlayer, false);
544	                                    if !desc2.is_empty() {
545	                                        let trigger = PendingTrigger::DamageToPlayerWatch {
546	                                            watcher_id,
547	                                            watcher_card_id,
548	                                            controller: watcher_controller,
549	                                            source_id,
550	                                            damaged_player: *damaged_player,
551	                                            amount: *amount,
552	                                            description: desc2,
553	                                        };
554	                                        if watcher_controller == active_player {
555	                                            ap_triggers.push(trigger);
556	                                        } else {
557	                                            nap_triggers.push(trigger);
558	                                        }
559	                                    }
560	                                }
561	                            }
562	                        }
563	                    }
564	                }
565	            }
566	            GameEvent::NonCombatDamageDealt { source, target, amount } => {
567	                // AnyDamageToPlayer watchers for non-combat damage.
568	                if let crate::events::DamageTarget::Player(damaged_player) = target {
569	                    let source_id = *source;
570	                    let watchers: Vec<(ObjectId, CardId, PlayerId)> = state.objects.values()
571	                        .filter(|o| o.zone == Zone::Battlefield)
572	                        .map(|o| (o.id, o.card_id, o.controller))
573	                        .collect();
574	                    for (watcher_id, watcher_card_id, watcher_controller) in watchers {
575	                        if registry.get(watcher_card_id).is_some() {
576	                            let desc = trigger_description(registry, watcher_card_id, &crate::cards::TriggerKind::AnyDamageToPlayer, false);
577	                            if !desc.is_empty() {
578	                                let trigger = PendingTrigger::DamageToPlayerWatch {
579	                                    watcher_id,
580	                                    watcher_card_id,
581	                                    controller: watcher_controller,
582	                                    source_id,
583	                                    damaged_player: *damaged_player,
584	                                    amount: *amount,
585	                                    description: desc,
586	                                };
587	                                if watcher_controller == active_player {
588	                                    ap_triggers.push(trigger);
589	                                } else {
590	                                    nap_triggers.push(trigger);
591	                                }
592	                            }
593	                        }
594	                    }
595	                }
596	            }
597	            GameEvent::StepStarted { step } => {
598	                let trigger_kind = match step {
599	                    crate::types::Step::Upkeep => Some(crate::cards::TriggerKind::Upkeep),
600	                    crate::types::Step::EndCombat => Some(crate::cards::TriggerKind::EndCombat),
601	                    crate::types::Step::EndStep => Some(crate::cards::TriggerKind::EndStep),
602	                    _ => None,
603	                };
604	                if let Some(kind) = trigger_kind {
605	                    let permanents: Vec<(ObjectId, CardId, PlayerId, bool)> = state.objects.values()
606	                        .filter(|o| o.zone == Zone::Battlefield)
607	                        .map(|o| (o.id, o.card_id, o.controller, o.is_transformed))
608	                        .collect();
609	                    for (obj_id, card_id, controller, is_transformed) in permanents {
610	                        if registry.get(card_id).is_some() {
611	                            let desc = trigger_description(registry, card_id, &kind, is_transformed);
612	                            if !desc.is_empty() {
613	                                let trigger = match kind {
614	                                    crate::cards::TriggerKind::Upkeep => PendingTrigger::UpkeepTrigger {
615	                                        object_id: obj_id,
616	                                        card_id,
617	                                        controller,
618	                                        description: desc,
619	                                    },
620	                                    crate::cards::TriggerKind::EndCombat => PendingTrigger::EndCombatTrigger {
621	                                        object_id: obj_id,
622	                                        card_id,
623	                                        controller,
624	                                        description: desc,
625	                                    },
626	                                    crate::cards::TriggerKind::EndStep => PendingTrigger::EndStepTrigger {
627	                                        object_id: obj_id,
628	                                        card_id,
629	                                        controller,
630	                                        description: desc,
631	                                    },
632	                                    _ => unreachable!(),
633	                                };
634	                                if controller == active_player {
635	                                    ap_triggers.push(trigger);
636	                                } else {
637	                                    nap_triggers.push(trigger);
638	                                }
639	                            }
640	                        }
641	                    }
642	                }
643	            }
644	            GameEvent::SpellCast { player: caster, object: spell_id } => {
645	                // Check if the spell is an instant or sorcery.
646	                let is_instant_sorcery = state.get_object(*spell_id)
647	                    .and_then(|o| registry.card_data(o.card_id))
648	                    .map(|d| d.card_types.iter().any(|ct| matches!(ct, crate::types::CardType::Instant | crate::types::CardType::Sorcery)))
649	                    .unwrap_or(false);
650	                if is_instant_sorcery {
651	                    let watchers: Vec<(ObjectId, CardId, PlayerId)> = state.objects.values()
652	                        .filter(|o| o.zone == Zone::Battlefield)
653	                        .map(|o| (o.id, o.card_id, o.controller))
654	                        .collect();
655	                    for (watcher_id, watcher_card_id, watcher_controller) in watchers {
656	                        if registry.get(watcher_card_id).is_some() {
657	                            let desc = trigger_description(registry, watcher_card_id, &crate::cards::TriggerKind::SpellCast, false);
658	                            if !desc.is_empty() {
659	                                let trigger = PendingTrigger::SpellCastWatch {
660	                                    watcher_id,
661	                                    watcher_card_id,
662	                                    controller: watcher_controller,
663	                                    caster: *caster,
664	                                    spell_id: *spell_id,
665	                                    description: desc,
666	                                };
667	                                if watcher_controller == active_player {
668	                                    ap_triggers.push(trigger);
669	                                } else {
670	                                    nap_triggers.push(trigger);
671	                                }
672	                            }
673	                        }
674	                    }
675	                }
676	            }
677	            GameEvent::AttackersDeclared { attackers } => {
678	                for (attacker_id, _defending_player) in attackers {
679	                    let (card_id, controller) = match state.get_object(*attacker_id) {
680	                        Some(o) if o.zone == Zone::Battlefield => (o.card_id, o.controller),
681	                        _ => continue,
682	                    };
683	                    if registry.get(card_id).is_some() {
684	                        let desc = trigger_description(registry, card_id, &crate::cards::TriggerKind::Attacks, false);
685	                        if !desc.is_empty() {
686	                            let trigger = PendingTrigger::AttacksTrigger {
687	                                object_id: *attacker_id,
688	                                card_id,
689	                                controller,
690	                                description: desc,
691	                            };
692	                            if controller == active_player {
693	                                ap_triggers.push(trigger);
694	                            } else {
695	                                nap_triggers.push(trigger);
696	                            }
697	                        }
698	                    }
699	                    // Also check equipment/auras attached to the attacker.
700	                    let attached: Vec<(ObjectId, CardId, PlayerId)> = state.objects.values()
701	                        .filter(|o| o.zone == Zone::Battlefield && o.attached_to == Some(*attacker_id))
702	                        .map(|o| (o.id, o.card_id, o.controller))
703	                        .collect();
704	                    for (eq_id, eq_card_id, eq_controller) in attached {
705	                        if registry.get(eq_card_id).is_some() {
706	                            let desc = trigger_description(registry, eq_card_id, &crate::cards::TriggerKind::Attacks, false);
707	                            if !desc.is_empty() {
708	                                let trigger = PendingTrigger::AttacksTrigger {
709	                                    object_id: eq_id,
710	                                    card_id: eq_card_id,
711	                                    controller: eq_controller,
712	                                    description: desc,
713	                                };
714	                                if eq_controller == active_player {
715	                                    ap_triggers.push(trigger);
716	                                } else {
717	                                    nap_triggers.push(trigger);
718	                                }
719	                            }
720	                        }
721	                    }
722	
723	                    // Attack-watchers: notify permanents that care about any creature attacking.
724	                    // Note: the attacker is NOT excluded — cards like Instigator Gang
725	                    // ("attacking creatures you control get +1/+0") must see their own attack.
726	                    let watchers: Vec<(ObjectId, CardId, PlayerId, bool)> = state.objects.values()
727	                        .filter(|o| o.zone == Zone::Battlefield)
728	                        .map(|o| (o.id, o.card_id, o.controller, o.is_transformed))
729	                        .collect();
730	                    for (w_id, w_card_id, w_controller, w_transformed) in watchers {
731	                        if registry.get(w_card_id).is_some() {
732	                            let desc = trigger_description(registry, w_card_id, &crate::cards::TriggerKind::AnyCreatureAttacks, w_transformed);
733	                            if !desc.is_empty() {
734	                                let trigger = PendingTrigger::AttackWatch {
735	                                    watcher_id: w_id,
736	                                    watcher_card_id: w_card_id,
737	                                    controller: w_controller,
738	                                    attacker_id: *attacker_id,
739	                                    attacker_controller: controller,
740	                                    description: desc,
741	                                };
742	                                if w_controller == active_player {
743	                                    ap_triggers.push(trigger);
744	                                } else {
745	                                    nap_triggers.push(trigger);
746	                                }
747	                            }
748	                        }
749	                    }
750	                }
751	            }
752	            GameEvent::BlockersDeclared { assignments } => {
753	                for (blocker_id, attacker_id) in assignments {
754	                    let (card_id, controller) = match state.get_object(*blocker_id) {
755	                        Some(o) if o.zone == Zone::Battlefield => (o.card_id, o.controller),
756	                        _ => continue,
757	                    };
758	                    if registry.get(card_id).is_some() {
759	                        let desc = trigger_description(registry, card_id, &crate::cards::TriggerKind::Blocks, false);
760	                        if !desc.is_empty() {
761	                            let trigger = PendingTrigger::BlocksTrigger {
762	                                object_id: *blocker_id,
763	                                card_id,
764	                                controller,
765	                                blocked_attacker: *attacker_id,
766	                                description: desc,
767	                            };
768	                            if controller == active_player {
769	                                ap_triggers.push(trigger);
770	                            } else {
771	                                nap_triggers.push(trigger);
772	                            }
773	                        }
774	                    }
775	                    // Also check equipment/auras attached to the blocker.
776	                    let attached: Vec<(ObjectId, CardId, PlayerId)> = state.objects.values()
777	                        .filter(|o| o.zone == Zone::Battlefield && o.attached_to == Some(*blocker_id))
778	                        .map(|o| (o.id, o.card_id, o.controller))
779	                        .collect();
780	                    for (eq_id, eq_card_id, eq_controller) in attached {
781	                        if registry.get(eq_card_id).is_some() {
782	                            let desc = trigger_description(registry, eq_card_id, &crate::cards::TriggerKind::Blocks, false);
783	                            if !desc.is_empty() {
784	                                let trigger = PendingTrigger::BlocksTrigger {
785	                                    object_id: eq_id,
786	                                    card_id: eq_card_id,
787	                                    controller: eq_controller,
788	                                    blocked_attacker: *attacker_id,
789	                                    description: desc,
790	                                };
791	                                if eq_controller == active_player {
792	                                    ap_triggers.push(trigger);
793	                                } else {
794	                                    nap_triggers.push(trigger);
795	                                }
796	                            }
797	                        }
798	                    }
799	
800	                    // BecomesBlocked: the attacker gets a "becomes blocked" trigger.
801	                    let (att_card_id, att_controller) = match state.get_object(*attacker_id) {
802	                        Some(o) if o.zone == Zone::Battlefield => (o.card_id, o.controller),
803	                        _ => continue,
804	                    };
805	                    if registry.get(att_card_id).is_some() {
806	                        let desc = trigger_description(registry, att_card_id, &crate::cards::TriggerKind::BecomesBlocked, false);
807	                        if !desc.is_empty() {
808	                            let trigger = PendingTrigger::BecomesBlockedTrigger {
809	                                object_id: *attacker_id,
810	                                card_id: att_card_id,
811	                                controller: att_controller,
812	                                blocker_id: *blocker_id,
813	                                description: desc,
814	                            };
815	                            if att_controller == active_player {
816	                                ap_triggers.push(trigger);
817	                            } else {
818	                                nap_triggers.push(trigger);
819	                            }
820	                        }
821	                    }
822	                    // Check equipment/auras on the attacker for BecomesBlocked triggers.
823	                    let att_attached: Vec<(ObjectId, CardId, PlayerId)> = state.objects.values()
824	                        .filter(|o| o.zone == Zone::Battlefield && o.attached_to == Some(*attacker_id))
825	                        .map(|o| (o.id, o.card_id, o.controller))
826	                        .collect();
827	                    for (eq_id, eq_card_id, eq_controller) in att_attached {
828	                        if registry.get(eq_card_id).is_some() {
829	                            let desc = trigger_description(registry, eq_card_id, &crate::cards::TriggerKind::BecomesBlocked, false);
830	                            if !desc.is_empty() {
831	                                let trigger = PendingTrigger::BecomesBlockedTrigger {
832	                                    object_id: eq_id,
833	                                    card_id: eq_card_id,
834	                                    controller: eq_controller,
835	                                    blocker_id: *blocker_id,
836	                                    description: desc,
837	                                };
838	                                if eq_controller == active_player {
839	                                    ap_triggers.push(trigger);
840	                                } else {
841	                                    nap_triggers.push(trigger);
842	                                }
843	                            }
844	                        }
845	                    }
846	                }
847	            }
848	            _ => {}
849	        }
850	    }
851	
852	    // Drain any pending triggers (e.g., state-triggered abilities added during SBA)
853	    // into the appropriate APNAP bucket.
854	    for t in state.pending_triggers.drain(..) {
855	        if t.controller() == active_player {
856	            ap_triggers.push(t);
857	        } else {
858	            nap_triggers.push(t);
859	        }
860	    }
861	
862	    // APNAP: Active player's triggers go on stack first (bottom),
863	    // non-active player's go on top. LIFO = NAP resolves first.
864	    use crate::state::StackEntry;
865	    for t in ap_triggers {
866	        state.stack.push(StackEntry::Trigger(t));
867	    }
868	    for t in nap_triggers {
869	        state.stack.push(StackEntry::Trigger(t));
870	    }
871	
872	    // Mark all events as processed.
873	    state.trigger_event_index = events.len();
874	}
